        "localizador": "L03"
      }
    ],
    "lacunas": [
      "As precedências e os requisitos de disponibilidade da ficha d_aa83 não estão presentes na view; não é possível determinar o efeito da disponibilidade do substituto em D6 sobre o marco final."
    ],
    "motivo": "As durações e a disponibilidade do substituto são conhecidas, mas faltam as relações necessárias para calcular o cronograma.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "Sem precedências e requisitos de disponibilidade, não se determina o término novo nem a variação frente a D10."
    ],
    "motivo": "A linha base é D10, mas o impacto do aviso no término não pode ser calculado com as relações ausentes.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base fixa declara orçamento de R$ 5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O custo total da extensão, se houver, depende de proposta sem valor ou teto definido; a duração da extensão também não pode ser determinada."
    ],
    "motivo": "O custo inclui a base e o adicional certo de R$ 200,00, mas o eventual preço de extensão impede apurar o total exato.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "A magnitude do eventual custo de extensão é desconhecida."
    ],
    "motivo": "O aviso acrescenta R$ 200,00 não incluídos na base; eventual extensão tem preço não negativo, portanto o custo aumenta, mas a magnitude total não é apurável.",
    "unidade": "BRL_centavo"
  }
}

